/**
 * Automatic Liveness Detection
 * Detects natural human behaviors without user prompts
 * - Blink detection
 * - Micro-movements (head, facial expressions)
 * - 3D depth perception
 * - Temporal consistency
 */

// Eye Aspect Ratio calculation for blink detection
const calculateEyeAspectRatio = (eyeLandmarks) => {
  // EAR = (||p2-p6|| + ||p3-p5||) / (2 * ||p1-p4||)
  // Vertical distances / horizontal distance

  const p1 = eyeLandmarks[0];
  const p2 = eyeLandmarks[1];
  const p3 = eyeLandmarks[2];
  const p4 = eyeLandmarks[3];
  const p5 = eyeLandmarks[4];
  const p6 = eyeLandmarks[5];

  const vertical1 = Math.sqrt(
    Math.pow(p2.x - p6.x, 2) + Math.pow(p2.y - p6.y, 2)
  );
  const vertical2 = Math.sqrt(
    Math.pow(p3.x - p5.x, 2) + Math.pow(p3.y - p5.y, 2)
  );
  const horizontal = Math.sqrt(
    Math.pow(p1.x - p4.x, 2) + Math.pow(p1.y - p4.y, 2)
  );

  if (horizontal === 0) return 0;

  return (vertical1 + vertical2) / (2.0 * horizontal);
};

// Extract eye landmarks from MediaPipe face mesh
const getEyeLandmarks = (landmarks) => {
  // MediaPipe Face Mesh indices for eyes
  const leftEye = [33, 160, 158, 133, 153, 144]; // Left eye landmarks
  const rightEye = [362, 385, 387, 263, 373, 380]; // Right eye landmarks

  return {
    left: leftEye.map(idx => landmarks[idx]),
    right: rightEye.map(idx => landmarks[idx])
  };
};

// Detect blinks from eye aspect ratio history
export const detectBlinks = (earHistory) => {
  if (earHistory.length < 10) return { blinkCount: 0, lastBlinkTime: null };

  const BLINK_THRESHOLD = 0.2; // EAR drops below this during blink
  const BLINK_CONSEC_FRAMES = 2; // Minimum consecutive frames

  let blinkCount = 0;
  let lastBlinkTime = null;
  let inBlink = false;
  let blinkFrames = 0;

  earHistory.forEach((entry, idx) => {
    if (entry.ear < BLINK_THRESHOLD) {
      blinkFrames++;
      if (blinkFrames >= BLINK_CONSEC_FRAMES && !inBlink) {
        blinkCount++;
        lastBlinkTime = entry.timestamp;
        inBlink = true;
      }
    } else {
      if (blinkFrames > 0) {
        blinkFrames = 0;
        inBlink = false;
      }
    }
  });

  return { blinkCount, lastBlinkTime };
};

// Calculate head pose (rotation) from landmarks
export const calculateHeadPose = (landmarks, imageWidth, imageHeight) => {
  // Use nose tip, chin, left/right eye outer corners for pose estimation
  const noseTip = landmarks[1];
  const chin = landmarks[152];
  const leftEye = landmarks[33];
  const rightEye = landmarks[263];
  const leftMouth = landmarks[61];
  const rightMouth = landmarks[291];

  // Normalize coordinates
  const nose = { x: noseTip.x * imageWidth, y: noseTip.y * imageHeight };
  const chinPoint = { x: chin.x * imageWidth, y: chin.y * imageHeight };
  const leftEyePoint = { x: leftEye.x * imageWidth, y: leftEye.y * imageHeight };
  const rightEyePoint = { x: rightEye.x * imageWidth, y: rightEye.y * imageHeight };

  // Calculate yaw (left-right rotation)
  const eyeDistance = Math.abs(rightEyePoint.x - leftEyePoint.x);
  const eyeCenter = (leftEyePoint.x + rightEyePoint.x) / 2;
  const noseOffset = nose.x - eyeCenter;
  const yaw = eyeDistance > 0 ? (noseOffset / eyeDistance) * 100 : 0; // -50 to +50 range

  // Calculate pitch (up-down rotation)
  const faceHeight = Math.abs(chinPoint.y - nose.y);
  const eyeY = (leftEyePoint.y + rightEyePoint.y) / 2;
  const noseRelative = (nose.y - eyeY) / (faceHeight > 0 ? faceHeight : 1);
  const pitch = noseRelative * 100; // Rough pitch estimation

  // Calculate roll (tilt)
  const eyeSlope = (rightEyePoint.y - leftEyePoint.y) / (rightEyePoint.x - leftEyePoint.x);
  const roll = Math.atan(eyeSlope) * (180 / Math.PI); // Degrees

  return { yaw, pitch, roll };
};

// Detect micro-movements over time
export const detectMicroMovements = (poseHistory) => {
  if (poseHistory.length < 30) return { movement: 0, variance: 0 };

  // Calculate variance in yaw and pitch
  const yaws = poseHistory.map(p => p.yaw);
  const pitches = poseHistory.map(p => p.pitch);

  const yawMean = yaws.reduce((sum, val) => sum + val, 0) / yaws.length;
  const pitchMean = pitches.reduce((sum, val) => sum + val, 0) / pitches.length;

  const yawVariance = yaws.reduce((sum, val) => sum + Math.pow(val - yawMean, 2), 0) / yaws.length;
  const pitchVariance = pitches.reduce((sum, val) => sum + Math.pow(val - pitchMean, 2), 0) / pitches.length;

  const totalVariance = yawVariance + pitchVariance;
  const movement = Math.sqrt(totalVariance);

  // Photos have near-zero variance, real faces have natural micro-movements
  return { movement, variance: totalVariance };
};

// Analyze 3D depth consistency
export const analyze3DDepth = (landmarks) => {
  // Check if face landmarks maintain realistic 3D relationships
  // Photos appear flat, real faces have depth

  const noseTip = landmarks[1];
  const leftCheek = landmarks[234];
  const rightCheek = landmarks[454];
  const forehead = landmarks[10];

  // Z-coordinates (depth) from MediaPipe
  const noseZ = noseTip.z || 0;
  const leftCheekZ = leftCheek.z || 0;
  const rightCheekZ = rightCheek.z || 0;
  const foreheadZ = forehead.z || 0;

  // Real faces: nose sticks out more than cheeks
  const noseDepth = Math.abs(noseZ - (leftCheekZ + rightCheekZ) / 2);

  // Real faces: forehead is further back than nose
  const foreheadDepth = Math.abs(foreheadZ - noseZ);

  // Combined depth score (higher = more 3D-like)
  const depthScore = (noseDepth + foreheadDepth) * 100;

  return {
    depthScore,
    noseProtrusion: noseDepth,
    foreheadRecession: foreheadDepth,
    is3D: depthScore > 5 // Threshold for 3D detection
  };
};

// Main liveness calculation
export const calculateLivenessScore = (livenessData) => {
  const {
    blinkCount = 0,
    timeSinceLastBlink = Infinity,
    microMovement = 0,
    depthScore = 0,
    earVariance = 0,
    poseVariance = 0,
    duration = 0
  } = livenessData;

  let score = 0;
  const factors = [];

  // Factor 1: Blink detection (30 points)
  if (blinkCount >= 1 && duration > 3000) {
    score += 30;
    factors.push({ name: 'Blink Detected', score: 30, status: 'pass' });
  } else if (duration < 3000) {
    score += 5;
    factors.push({ name: 'Waiting for Blink', score: 5, status: 'pending' });
  } else {
    factors.push({ name: 'No Blink Detected', score: 0, status: 'fail' });
  }

  // Factor 2: Micro-movements (25 points)
  if (microMovement > 2 && microMovement < 50) {
    // Natural movement range
    const movementScore = Math.min(25, (microMovement / 10) * 25);
    score += movementScore;
    factors.push({ name: 'Natural Movement', score: Math.round(movementScore), status: 'pass' });
  } else if (microMovement <= 2) {
    factors.push({ name: 'Too Static (Photo?)', score: 0, status: 'fail' });
  } else {
    factors.push({ name: 'Too Much Movement', score: 5, status: 'warn' });
    score += 5;
  }

  // Factor 3: 3D Depth (20 points)
  if (depthScore > 5) {
    const depthPoints = Math.min(20, (depthScore / 15) * 20);
    score += depthPoints;
    factors.push({ name: '3D Face Detected', score: Math.round(depthPoints), status: 'pass' });
  } else {
    factors.push({ name: 'Flat/2D Surface', score: 0, status: 'fail' });
  }

  // Factor 4: Eye movement variance (15 points)
  if (earVariance > 0.001 && earVariance < 0.1) {
    const earPoints = Math.min(15, (earVariance / 0.01) * 15);
    score += earPoints;
    factors.push({ name: 'Eye Movement', score: Math.round(earPoints), status: 'pass' });
  } else {
    factors.push({ name: 'No Eye Movement', score: 0, status: 'fail' });
  }

  // Factor 5: Pose variance (10 points)
  if (poseVariance > 5 && poseVariance < 500) {
    const posePoints = Math.min(10, (poseVariance / 50) * 10);
    score += posePoints;
    factors.push({ name: 'Head Movement', score: Math.round(posePoints), status: 'pass' });
  } else if (poseVariance <= 5) {
    factors.push({ name: 'No Head Movement', score: 0, status: 'fail' });
  }

  // Normalize to 0-1
  const confidence = Math.min(1, score / 100);

  return {
    confidence,
    rawScore: score,
    factors,
    blinkCount,
    timeSinceLastBlink,
    microMovement,
    depthScore
  };
};

// Process frame for liveness detection
export const processLivenessFrame = (landmarks, imageWidth, imageHeight) => {
  // Extract eye landmarks
  const eyes = getEyeLandmarks(landmarks);

  // Calculate Eye Aspect Ratio for both eyes
  const leftEAR = calculateEyeAspectRatio(eyes.left);
  const rightEAR = calculateEyeAspectRatio(eyes.right);
  const avgEAR = (leftEAR + rightEAR) / 2;

  // Calculate head pose
  const pose = calculateHeadPose(landmarks, imageWidth, imageHeight);

  // Analyze 3D depth
  const depth = analyze3DDepth(landmarks);

  return {
    ear: avgEAR,
    pose,
    depth,
    timestamp: Date.now()
  };
};

export default {
  processLivenessFrame,
  detectBlinks,
  detectMicroMovements,
  analyze3DDepth,
  calculateLivenessScore
};
